/**
 * Extracts concrete visual keywords from `<lora_check>` (excluding any "Drop/Discard/Skip" lines)
 * or fallback LoRA description block and checks whether the target prompt text reflects them.
 */
export function verifyPromptReflectsLoraCheck(
  prompt: string,
  loraCheck: string | null,
  fallbackLoraBlock?: string | null
): { passed: boolean; expectedKeywords: string[]; matchedKeywords: string[] } {
  const rawLines = (loraCheck || fallbackLoraBlock || '').split(/\r?\n/);

  // If the self-check explicitly notes a user-requested pivot/override away from an old LoRA, skip lines marked skipped/pivoted/dropped
  const sourceLines = rawLines
    .filter(
      (line) =>
        !/\b(?:drop|dropped|discard|discarded|ignore|ignored|remove|removed|skip|skipped|user\s+pivot|overridden)\s*:/i.test(
          line
        ) &&
        !/^attached\s+loras\b/i.test(line.trim()) &&
        !/^active\s+non-character\s+loras\b/i.test(line.trim())
    )
    .map((line) =>
      line
        .replace(/^(?:[-*•]\s*)?[^:\n]{1,50}:\s*/, '')
        .replace(/\[(?:concept|clothing|style|pose|lighting|character|unclassified)\]/gi, ' ')
    );

  const rawWords = sourceLines
    .join(' ')
    .toLowerCase()
    .replace(/[^a-z0-9\s-]/g, ' ')
    .split(/\s+/)
    .map((w) => w.replace(/^-+|-+$/g, ''))
    .filter((w) => w.length >= 4 && !VERIFICATION_STOPWORDS.has(w) && !/^\d+$/.test(w));

  const expectedKeywords = Array.from(new Set(rawWords));
  if (expectedKeywords.length < 2) {
    return { passed: true, expectedKeywords, matchedKeywords: expectedKeywords };
  }

  const promptLower = prompt.toLowerCase();
  const matchedKeywords = expectedKeywords.filter((kw) => {
    const stem = kw.length >= 6 ? kw.replace(/(?:ing|ed|es|s)$/, '') : kw;
    return promptLower.includes(kw) || (stem.length >= 4 && promptLower.includes(stem));
  });

  return {
    passed: matchedKeywords.length >= 1,
    expectedKeywords,
    matchedKeywords,
  };
}

/**
 * Extracts only permanent physical/identity tags from raw WD14 tags for Character Portrait analysis.
 */
export function extractCharacterIdentityTags(tags: string[]): string[] {
  const identityRegex =
    /^(?:1girl|1boy|solo|woman|man|mature female|mature male|girl|boy)$|\b(?:hair|eyes|skin|freckles|mole|scar|tattoo|fangs|pointy ears|elf ears|heterochromia|glasses|eyebrows|lips|eyelashes|cheek|jawline|bust|breasts|chest|hips|waist|thighs|build|slender|curvy|voluptuous|petite|athletic|muscular|plump|toned|abs|tall|short|tan|tanlines|caucasian|asian|latina|ebony)\b/i;
  const excludeTemporaryRegex =
    /\b(?:looking at|smile|smiling|blush|open mouth|closed eyes|winking|parted lips|sitting|standing|lying|kneeling|shirt|dress|skirt|jacket|bikini|lingerie|bra|panties|stockings|shoes|boots|hat|background|indoors|outdoors|lighting|shadow)\b/i;

  return tags.filter((tag) => identityRegex.test(tag) && !excludeTemporaryRegex.test(tag));
}

/**
 * Pre-filters WD14 tags when a character is attached in Quick Gen:
 * strips only hair color and eye color tags while preserving expressions, poses, clothing, and props.
 */
export function filterCharacterIdentityTags(tags: string[]): string[] {
  const hairColorRegex =
    /\b(?:blonde|blond|brown|dark[\s_]brown|light[\s_]brown|black|red|pink|blue|dark[\s_]blue|light[\s_]blue|green|purple|light[\s_]purple|orange|silver|grey|gray|white|aqua|platinum|auburn|chestnut|ginger|multicolored|two-tone|streaked|colored|gradient|bleached)[\s_]+hair\b/i;

  const eyeColorRegex =
    /\b(?:blue|brown|green|red|yellow|purple|aqua|amber|grey|gray|pink|orange|black|golden|hazel|multicolored)[\s_]+eyes\b|\bheterochromia\b/i;

  return tags.filter((tag) => !hairColorRegex.test(tag) && !eyeColorRegex.test(tag));
}

/**
 * Post-processes an interrogated prompt when a character is selected, scoped strictly
 * to hair color and eye color so object/prop/setting descriptors remain untouched.
 */
export function stripCharacterPhysicalTraits(prompt: string): string {
  let cleaned = prompt;
  const hairColors =
    '(?:platinum\\s+blonde|strawberry\\s+blonde|dirty\\s+blonde|ash\\s+blonde|golden\\s+blonde|light\\s+brown|dark\\s+brown|jet[\\s-]black|raven[\\s-]black|fiery\\s+red|chestnut\\s+brown|copper|ginger|auburn|chestnut|mahogany|brunette|blonde|blond|brown|black|red|pink|blue|green|purple|teal|cyan|orange|lavender|silver|grey|gray|white|pastel|dyed|bleached)';
  const hairNouns =
    '(?:hair|locks|tresses|curls|waves|strands|ponytail|twintails|braid|braids|bun|bangs)';
  const hairStyleMid =
    '(?:(?:long|short|medium|shoulder-length|waist-length|wavy|curly|straight|messy|tousled|braided|flowing|sleek|layered|cropped|shoulder\\s+length)\\s+){0,2}';

  cleaned = cleaned.replace(
    new RegExp(`\\b${hairColors}\\s+(?=${hairStyleMid}${hairNouns}\\b)`, 'gi'),
    ''
  );
  cleaned = cleaned.replace(
    /\b(?:blonde-haired|blond-haired|brown-haired|dark-haired|black-haired|red-haired|silver-haired|white-haired|pink-haired|blue-haired|raven-haired|ginger-haired|auburn-haired)\b/gi,
    ''
  );
  cleaned = cleaned.replace(
    /\b(?:blonde|blond|brunette|redhead)\s+(?=(?:woman|man|girl|boy|person|subject|female|male|model|figure)\b)/gi,
    ''
  );
  cleaned = cleaned.replace(/\bwith\s+hair\b/gi, '');

  cleaned = cleaned.replace(
    /\b(?:and\s+)?(?:with\s+)?(?:piercing\s+|bright\s+|deep\s+|warm\s+|dark\s+|light\s+|striking\s+|vivid\s+|pale\s+|glowing\s+)?(?:blue|brown|green|hazel|amber|grey|gray|violet|purple|crimson|red|golden|yellow|aqua|emerald|sapphire)\s+eyes\b/gi,
    ''
  );
  cleaned = cleaned.replace(
    /\b(?:blue-eyed|brown-eyed|green-eyed|hazel-eyed|dark-eyed|amber-eyed|grey-eyed|gray-eyed|violet-eyed|red-eyed|heterochromia)\b/gi,
    ''
  );

  cleaned = cleaned
    .replace(/\bwith\s+(?:and|in|on|at|wearing|dressed)\b/gi, (m) => m.replace(/^with\s+/i, ''))
    .replace(/\bwith\s*[,.;:]/gi, ',')
    .replace(/,\s*and\s*,/gi, ',')
    .replace(/\band\s*[,.;:]/gi, ',')
    .replace(/\(\s*\)/g, '')
    .replace(/\s*,\s*,+/g, ',')
    .replace(/\s{2,}/g, ' ')
    .trim();

  return cleaned;
}

/**
 * Ensures high-confidence WD14 nudity/anatomical exposure tags are never silently skipped
 * or reduced to vague euphemisms in an interrogated Vision LLM prompt.
 */
export function mergeMissedExposureCues(
  prompt: string,
  cues: Wd14ExposureCues | null | undefined
): string {
  if (!cues?.hasNudityOrExplicit || cues.highConfidenceTags.length === 0) {
    return prompt;
  }

  const tags = new Set(cues.highConfidenceTags.map((t) => t.toLowerCase()));
  const additions: string[] = [];

  if (tags.has('completely nude')) {
    if (!/\b(?:completely\s+nude|fully\s+nude|entirely\s+nude|fully\s+naked)\b/i.test(prompt)) {
      if (!/\b(?:nude|naked)\b/i.test(prompt)) additions.push('completely nude');
    }
  } else if (tags.has('nude') || tags.has('naked')) {
    if (!/\b(?:nude|naked|unclothed|fully\s+undressed)\b/i.test(prompt)) {
      additions.push('nude');
    }
  }

  if (
    tags.has('topless') &&
    !/\b(?:topless|bare\s+breasts?|exposed\s+breasts?|shirtless)\b/i.test(prompt)
  ) {
    additions.push('topless');
  }
  if (
    tags.has('bottomless') &&
    !/\b(?:bottomless|no\s+pants|pantiless|exposed\s+(?:genitals?|vulva|pussy|penis))\b/i.test(
      prompt
    )
  ) {
    additions.push('bottomless');
  }
  if (
    (tags.has('nipples') || tags.has('areolae') || tags.has('areola')) &&
    !/\b(?:nipples?|areolae?)\b/i.test(prompt)
  ) {
    additions.push('exposed breasts and nipples');
  }
  if (
    (tags.has('pussy') || tags.has('vaginal')) &&
    !/\b(?:pussy|vulva|vagina|vaginal|labia|exposed\s+genitals?)\b/i.test(prompt)
  ) {
    additions.push('exposed vulva');
  }
  if (
    (tags.has('penis') || tags.has('testicles') || tags.has('erection')) &&
    !/\b(?:penis|cock|shaft|testicles|scrotum|erection|exposed\s+genitals?)\b/i.test(prompt)
  ) {
    additions.push('exposed penis');
  }
  if (tags.has('pubic hair') && !/\b(?:pubic\s+hair|pubic|trimmed\s+hair|bush)\b/i.test(prompt)) {
    additions.push('visible pubic hair');
  }
  if (
    tags.has('spread legs') &&
    !/\b(?:spread(?:ing)?\s+(?:her|his|their)?\s*legs|legs\s+(?:spread|apart|parted|wide))\b/i.test(
      prompt
    )
  ) {
    additions.push('legs spread wide');
  }
  if (
    (tags.has('panties aside') || tags.has('clothing aside')) &&
    !/\b(?:pulled\s+aside|pushed\s+aside|shifted\s+aside|aside)\b/i.test(prompt)
  ) {
    additions.push('clothing pulled aside');
  }
  if (
    (tags.has('no panties') || tags.has('no underwear')) &&
    !/\b(?:no\s+panties|no\s+underwear|pantiless|without\s+(?:panties|underwear))\b/i.test(prompt)
  ) {
    additions.push('no underwear');
  }
  if (tags.has('no bra') && !/\b(?:no\s+bra|braless|without\s+(?:a\s+)?bra)\b/i.test(prompt)) {
    additions.push('no bra');
  }
  if (
    tags.has('see-through') &&
    !/\b(?:see-through|sheer|transparent|translucent)\b/i.test(prompt)
  ) {
    additions.push('sheer see-through fabric');
  }

  if (additions.length === 0) return prompt;
  const trimmed = prompt.trim().replace(/[.,;:\s]+$/, '');
  return `${trimmed}, ${additions.join(', ')}`;
}
